package net.civeira.phylax.features.access.trustedclient.domain.valueobject;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import net.civeira.phylax.common.exception.ConstraintException;

class UserinfoEncryptedResponseEncVOUnitTest {

  /**
   * @autogenerated ValueObjectGenerator
   */
  @Test
  @DisplayName("Test value object contruction for property userinfo encrypted response enc of trusted client ")
  void test_userinfo_encrypted_response_enc_v_o_builder() {
    Assertions.assertFalse(
        UserinfoEncryptedResponseEncVO.nullValue().getUserinfoEncryptedResponseEnc().isPresent(),
        "A empty vo should have a null value");
    Assertions.assertFalse(
        UserinfoEncryptedResponseEncVO.tryFrom(null).getUserinfoEncryptedResponseEnc().isPresent(),
        "With a null value, no present result");
    Assertions.assertEquals("one",
        UserinfoEncryptedResponseEncVO.from("one").getUserinfoEncryptedResponseEnc().orElse(null));
    Object falingInstance = new Object() {};
    Assertions.assertThrows(ConstraintException.class,
        () -> UserinfoEncryptedResponseEncVO.tryFrom(falingInstance));
    Assertions.assertEquals("[" + "one" + "]",
        UserinfoEncryptedResponseEncVO.from("one").toString());
  }
}
